(() => {
  const style = document.createElement('style');
  style.textContent = `
    :root{--forest:#356c4d;--moss:#728d68;--cream:#f7f3ea;--sand:#f1eadc;--accent:#963436;--ink:#183c32;--muted:#68766c}
    html[data-theme="dark"]{--cream:#1d1b18;--sand:#332f28;--white:#26231e;--line:#474136;--ink:#f4eee4;--muted:#cfc3b2;--forest:#5f9269;--moss:#b8c9aa;--accent:#c45b59}
    html[data-theme="dark"] body{background:#1f2f2a}html[data-theme="dark"] .nav{background:rgba(31,47,42,.96)}html[data-theme="dark"] .hero{background:radial-gradient(circle at 80% 18%,#466e5a 0,transparent 33%),linear-gradient(125deg,#1f2f2a,#29453a)}html[data-theme="dark"] .hero-card{background:linear-gradient(145deg,#285947,#1f493b)}html[data-theme="dark"] .story{background:linear-gradient(135deg,#234d3e,#173a30)}html[data-theme="dark"] .catalog{background:#233a32}html[data-theme="dark"] .event{background:#2a4038;border-color:#50685e}html[data-theme="dark"] .footer{background:#152820}html[data-theme="dark"] .btn-primary{background:#a84c4e}html[data-theme="dark"] .navlinks a,html[data-theme="dark"] .lead,html[data-theme="dark"] .cabin-meta,html[data-theme="dark"] .price,html[data-theme="dark"] .linkbtn,html[data-theme="dark"] .cabin-body h3{color:#f7f2e8!important}html[data-theme="dark"] .card{background:#29473c;border-color:#547567}html[data-theme="dark"] .event-meta{color:#ffaaa5!important}
    .topbar{background:#943336}.btn-primary{background:#9d3435}.hero-card{background:linear-gradient(145deg,#1f5545,#346b57)}.story{background:linear-gradient(135deg,#1b493a,#28604d)}
    .event{padding:0;overflow:hidden;background:var(--white);border:1px solid var(--line);box-shadow:0 12px 30px rgba(21,57,46,.10)}.event-main{width:100%;height:220px;object-fit:cover;display:block}.event-copy{padding:21px}.event b{font-size:21px}.event p{color:var(--muted);line-height:1.55}.event-meta{font-size:13px;color:#9d3435;font-weight:850;letter-spacing:.04em;margin-bottom:6px}.event:hover{transform:translateY(-4px);transition:.2s}.gallery-button{background:transparent;border:0;color:var(--forest);font:inherit;font-weight:800;padding:0;cursor:pointer}.salon-modal{position:fixed;inset:0;z-index:100;background:rgba(12,28,23,.78);display:grid;place-items:center;padding:20px}.salon-modal[hidden]{display:none}.salon-modal-box{position:relative;width:min(900px,100%);max-height:90vh;overflow:auto;background:var(--cream);border-radius:20px;padding:18px}.salon-modal img{width:100%;max-height:510px;object-fit:cover;border-radius:13px}.salon-modal .thumbs{display:flex;gap:8px;overflow:auto;margin-top:10px}.salon-modal .thumbs img{width:100px;height:68px;object-fit:cover;cursor:pointer}.salon-modal .close{position:absolute;right:28px;top:28px;background:#9d3435;color:white;border:0;border-radius:50%;width:38px;height:38px;font-size:24px;cursor:pointer}html[data-theme="dark"] body,html[data-theme="dark"] .catalog,html[data-theme="dark"] .register,html[data-theme="dark"] .visitor-hub{background:#1d1b18!important}html[data-theme="dark"] .nav,html[data-theme="dark"] .story,html[data-theme="dark"] .hero,html[data-theme="dark"] .hero-card{background:#26231e!important}html[data-theme="dark"] .card,html[data-theme="dark"] .event,html[data-theme="dark"] .hub-card{background:#26231e!important;border-color:#474136!important}html[data-theme="dark"] .footer{background:#1d1b18!important}html[data-theme="dark"] .btn-primary{background:#5f9269!important}@media(max-width:800px){.event-main{height:210px}}
  `;
  document.head.append(style);
  const halls=[
    ['Salón Darwin',[2,3,4,5,6],'250 personas · 240 m²','Un gran salón para ceremonias religiosas, matrimonios y eventos especiales. Servicio completo de sonido, iluminación, animación, música y montaje.'],
    ['Salón Orgánico',[7,8,9,10,11],'150 personas · 160 m²','Un espacio rodeado de áreas verdes y piscina, con terraza para ceremonias. Ideal para paseos, capacitaciones, matrimonios, retiros y celebraciones.'],
    ['Quincho Club House',[12,13,14,15],'120 en salón · 40 en quincho','Salón, quincho, asaderas, áreas verdes, piscina y espacios de entretención para grupos y celebraciones al aire libre.']
  ];
  const grid=document.querySelector('.event-grid');
  const modal=document.createElement('div');modal.className='salon-modal';modal.hidden=true;document.body.append(modal);
  const open=(hall)=>{let current=0;const render=()=>{const photos=hall[1].map(n=>`assets/salones/${n}.jpg`);modal.innerHTML=`<div class="salon-modal-box"><button class="close" aria-label="Cerrar">×</button><img src="${photos[current]}" alt="${hall[0]}"><div class="thumbs">${photos.map((src,i)=>`<img src="${src}" data-i="${i}" alt="Foto ${i+1} de ${hall[0]}">`).join('')}</div><h2>${hall[0]}</h2><p>${hall[3]}</p></div>`;modal.querySelector('.close').onclick=()=>modal.hidden=true;modal.querySelectorAll('[data-i]').forEach(x=>x.onclick=()=>{current=+x.dataset.i;render()})};render();modal.hidden=false};
  if(grid) {grid.innerHTML=halls.map(h=>`<article class="event"><img class="event-main" loading="lazy" src="assets/salones/${h[1][0]}.jpg" alt="${h[0]}, Fundo El Grillo"><div class="event-copy"><div class="event-meta">${h[2]}</div><b>${h[0]}</b><p>${h[3]}</p><button class="gallery-button" data-hall="${h[0]}">Ver galería completa →</button></div></article>`).join('');grid.querySelectorAll('[data-hall]').forEach(btn=>btn.onclick=()=>open(halls.find(h=>h[0]===btn.dataset.hall)))}
})();
